# IPTVPremium: Retorno do catalogo, sessoes retidas e prioridade dos detalhes. Base: java.zip atual + icones. Windows PowerShell 5.1 / PowerShell 7.
[CmdletBinding()]
param([string]$Projeto = (Get-Location).Path)
Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
function Get-BytesHash([byte[]]$Bytes) {
    $sha = [Security.Cryptography.SHA256]::Create()
    try { return ([BitConverter]::ToString($sha.ComputeHash($Bytes))).Replace('-', '') }
    finally { $sha.Dispose() }
}
function Get-TextHash([byte[]]$Bytes) {
    $text = [Text.Encoding]::UTF8.GetString($Bytes).TrimStart([char]0xFEFF).Replace("`r`n", "`n")
    return Get-BytesHash ([Text.Encoding]::UTF8.GetBytes($text))
}
$files = @(
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/core/navigation/AppNavigation.kt'; Binary = $false; Allowed = @('E2221DE66ED01DDED3804761C4F1B836EC63C418A2DB2AC93224FDDBB68223CC'); MayCreate = $false; After = '87DAC584B67F4CA303D2EE9B2D3AE843C0701551A47BFBE09362E58A1A93E14D'; PayloadHash = '87DAC584B67F4CA303D2EE9B2D3AE843C0701551A47BFBE09362E58A1A93E14D'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/data/cache/CatalogSessionRevisions.kt'; Binary = $false; Allowed = @(); MayCreate = $true; After = '5255CAD9C4CE54D5AB67B992BDB243AF1CDA03350C7709FAC896D58BD5A0923C'; PayloadHash = '5255CAD9C4CE54D5AB67B992BDB243AF1CDA03350C7709FAC896D58BD5A0923C'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/live/LiveTvViewModel.kt'; Binary = $false; Allowed = @('3467FFB248351F18808FA48F992C79302A7B4C55DDFC05526583DCC96547E515'); MayCreate = $false; After = '768064C9278253141BFCD3344E6506E6CF969D3C88F24869537E8212E7890758'; PayloadHash = '768064C9278253141BFCD3344E6506E6CF969D3C88F24869537E8212E7890758'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MovieDetailsScreen.kt'; Binary = $false; Allowed = @('87468FEC3EE1F7866CF585A759E069BDCB13C650D7FB8F8AE5E974E0869A7AF2'); MayCreate = $false; After = '516718AAE280F1357166984E71E5CC6551650FBF8DC9D6E1C82115B26C116782'; PayloadHash = '516718AAE280F1357166984E71E5CC6551650FBF8DC9D6E1C82115B26C116782'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MovieOpeningPolicy.kt'; Binary = $false; Allowed = @('C8BBFF429BDCAD13BB31BE85BBA73159721D596C810A66FF4BF3B2A6831B26FC'); MayCreate = $false; After = '7C34CC7D3A4C14DD578D94650C93FCAFF62AD41C07EF4E6CFEC2BBC1C648049A'; PayloadHash = '7C34CC7D3A4C14DD578D94650C93FCAFF62AD41C07EF4E6CFEC2BBC1C648049A'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MoviesScreen.kt'; Binary = $false; Allowed = @('B28058C9ED8F6A4B2C1F24F279BF89CD9220F289F2D652A134C7CDB1B21A88F0'); MayCreate = $false; After = '38FFC2D84CA73EB7C694CCDCD8FFFBA4B338DA50DE89549811B2C9AF23D11F24'; PayloadHash = '38FFC2D84CA73EB7C694CCDCD8FFFBA4B338DA50DE89549811B2C9AF23D11F24'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/movies/MoviesViewModel.kt'; Binary = $false; Allowed = @('F8036CDC900F86BD5F26A7B2C35067E5DD47FBC79115C22CEAE77A9BAEE4C8D6'); MayCreate = $false; After = '143CE1E703888D4E3BE9D60A41D4A89264A34715149FF82B2B7C1DE9AFCA6777'; PayloadHash = '143CE1E703888D4E3BE9D60A41D4A89264A34715149FF82B2B7C1DE9AFCA6777'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/series/SeriesLoadingOverlay.kt'; Binary = $false; Allowed = @('1B7A889F6721E4791B7AE70B8110AA6D8326FA0A0C4547EE2356B87E3C5E3A32'); MayCreate = $false; After = 'A4732A21270E8429AC24B393E1042E2A88CE46F87088D7C59297FCDD225F9FEA'; PayloadHash = 'A4732A21270E8429AC24B393E1042E2A88CE46F87088D7C59297FCDD225F9FEA'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/series/SeriesOpeningTiming.kt'; Binary = $false; Allowed = @('1C1D0A8D4E77A0B6C50F8E4B0C7C4B71D5F572565488D71E291421B5F8DBFDEF'); MayCreate = $false; After = '4AF3969B90EB666ACA9EDF3E36700A26C86022D12A0A8D08446C3DAD5CDB7547'; PayloadHash = '4AF3969B90EB666ACA9EDF3E36700A26C86022D12A0A8D08446C3DAD5CDB7547'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/series/SeriesScreen.kt'; Binary = $false; Allowed = @('E919EDCF52391385FA9D0D2FB0C797BB8D61FC3004BE653F54265512808BADFA'); MayCreate = $false; After = 'F5B5D2E8990A572C81992B6A79C02826122EC6E3F3C7E848708B5D354855AEE1'; PayloadHash = 'F5B5D2E8990A572C81992B6A79C02826122EC6E3F3C7E848708B5D354855AEE1'; Data = '' },
    @{ Path = 'app/src/main/java/br/com/flaviotorres/iptvpremium/ui/series/SeriesViewModel.kt'; Binary = $false; Allowed = @('6B8B1C99D1AC1B3B2B35F18C1311541060BEC2D66F8C7B45D3B8EE5B074171E0'); MayCreate = $false; After = '244EFD4C206982645F930622F2A1FAA8D9408CDC45DB33789CBAEE1A960FB5E3'; PayloadHash = '244EFD4C206982645F930622F2A1FAA8D9408CDC45DB33789CBAEE1A960FB5E3'; Data = '' }
)
$root = (Resolve-Path -LiteralPath $Projeto).Path
if (!(Test-Path -LiteralPath (Join-Path $root 'app/build.gradle.kts'))) {
    throw 'Abra o terminal na raiz de IPTVPremium (pasta com app e gradlew), ou informe -Projeto.'
}
# Verifica a versao de todos os arquivos antes de escrever qualquer mudanca.
$pending = @()
foreach ($file in $files) {
    $path = Join-Path $root $file.Path
    $present = Test-Path -LiteralPath $path -PathType Leaf
    $original = $null
    if ($present) {
        $original = [IO.File]::ReadAllBytes($path)
        $current = if ($file.Binary) { Get-BytesHash $original } else { Get-TextHash $original }
        if ($current -eq $file.After) { continue }
        if ($file.Allowed -notcontains $current) {
            throw "Arquivo com mudancas diferentes da versao enviada: $($file.Path). Nada foi alterado; suas mudancas foram preservadas."
        }
    } elseif (!$file.MayCreate) {
        throw "Arquivo necessario ausente: $($file.Path). Nada foi alterado."
    }
    $packed = [IO.MemoryStream]::new([Convert]::FromBase64String($file.Data))
    $gzip = [IO.Compression.GZipStream]::new($packed, [IO.Compression.CompressionMode]::Decompress)
    $plain = [IO.MemoryStream]::new()
    try { $gzip.CopyTo($plain); $bytes = $plain.ToArray() }
    finally { $gzip.Dispose(); $plain.Dispose(); $packed.Dispose() }
    if ((Get-BytesHash $bytes) -ne $file.PayloadHash) { throw 'Pacote com integridade invalida. Nada foi alterado.' }
    $pending += @{ Path = $path; Relative = $file.Path; Bytes = $bytes; Original = $original; Present = $present; Hash = $file.PayloadHash }
}
if ($pending.Count -eq 0) {
    Write-Host 'Esta atualizacao ja esta aplicada.' -ForegroundColor Green
    return
}
$backup = Join-Path $root ('.navigation-backups/catalogo-retorno-prioridade-' + (Get-Date -Format 'yyyyMMdd-HHmmss') + '-' + [guid]::NewGuid().ToString('N').Substring(0,8))
[IO.Directory]::CreateDirectory($backup) | Out-Null
foreach ($file in $pending) {
    if ($file.Present) {
        $copy = Join-Path $backup $file.Relative
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($copy)) | Out-Null
        [IO.File]::Copy($file.Path, $copy, $false)
        if ((Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash -ne (Get-BytesHash $file.Original)) {
            throw 'Backup nao passou na verificacao. Nenhum arquivo do projeto foi alterado.'
        }
    }
}
@($pending | ForEach-Object { @{ path = $_.Relative; existed = $_.Present } }) |
    ConvertTo-Json | Set-Content -LiteralPath (Join-Path $backup 'manifest.json') -Encoding UTF8
try {
    foreach ($file in $pending) {
        [IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($file.Path)) | Out-Null
        [IO.File]::WriteAllBytes($file.Path, $file.Bytes)
        if ((Get-FileHash -LiteralPath $file.Path -Algorithm SHA256).Hash -ne $file.Hash) { throw "Falha ao gravar $($file.Relative)." }
    }
} catch {
    foreach ($file in $pending) {
        if ($file.Present) { [IO.File]::WriteAllBytes($file.Path, $file.Original) }
        elseif (Test-Path -LiteralPath $file.Path -PathType Leaf) { [IO.File]::Delete($file.Path) }
    }
    throw
}
Write-Host 'Atualizacao aplicada: retorno sem selecao presa, sessoes de catalogo retidas e detalhes prioritarios.' -ForegroundColor Green
Write-Host "Backup: $backup"
Write-Host 'Compile e execute pelo Android Studio para validar no seu aparelho.'
